  font-weight: 700;
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  gap: 8px;
}

/* ====== PROJECTS PAGE ====== */
.projects-hero {
  padding: 48px 0 24px;
}
.projects-hero h1 {
