  width: 100%;
  display: block;
}
.project-card .winner-badge {
  position: absolute;
  top: 10px;
  left: 10px;
  background: var(--yellow);
  color: var(--dark);
  font-size: 11px;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 4px;
  text-transform: uppercase;
}
.project-card .project-info {
  padding: 14px 16px;
}
.project-card .project-title {
  font-size: 14px;
  font-weight: 700;
  margin-bottom: 4px;
}
.project-card .project-user {
  font-size: 13px;
  color: var(--gray-500);
  margin-bottom: 8px;
}
.project-card .project-stats {
  display: flex;
  gap: 14px;
  font-size: 12px;
  color: var(--gray-400);
}
.project-card .project-stats span {
  display: flex;
  align-items: center;
