  margin-bottom: 4px;
}
.pricing-card .plan-price span { font-size: 18px; font-weight: 500; color: var(--gray-500); }
.pricing-card .billed-as {
  font-size: 14px;
  color: var(--gray-500);
  margin-bottom: 20px;
}
.pricing-card .plan-features {
  margin-bottom: 24px;
}
.pricing-card .plan-features li {
