  margin-bottom: 8px;
}
.benefit-card p {
  font-size: 14px;
  color: var(--gray-500);
  line-height: 1.55;
}

/* FAQ */
.faq-section { padding: 60px 0; }
.faq-section h2 {
  font-size: 32px;
  font-weight: 800;
  text-align: center;
  margin-bottom: 40px;
}
.faq-list { max-width: 760px; margin: 0 auto; }
.faq-item {
  border-bottom: 1px solid var(--gray-200);
}
.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 0;
  font-size: 16px;
