  .hero-slide-image { height: 200px; }
  .hero-pricing .sale { font-size: 26px; }

  .section-header h2 { font-size: 22px; }
  .course-grid { grid-template-columns: repeat(2, 1fr); gap: 16px; }

  .value-grid { grid-template-columns: 1fr; gap: 16px; }
  .value-card { text-align: left; display: flex; gap: 16px; align-items: flex-start; }
  .value-icon { margin: 0; flex-shrink: 0; }

  .footer-grid { grid-template-columns: 1fr; gap: 0; }
  .footer-col { border-bottom: 1px solid var(--gray-700); }
  .footer-col h4 {
    padding: 16px 0;
    margin-bottom: 0;
    display: flex;
    align-items: center;
    justify-content: space-between;
    cursor: pointer;
  }
  .footer-col h4::after { content: "+"; font-size: 20px; font-weight: 400; }
